  readonly dark = computed(() => (this.choice() ?? (this.systemPrefersDark() ? 'dark' : 'light')) === 'dark');

  readonly themeLabel = computed(() => (this.dark() ? 'Switch to light theme' : 'Switch to dark theme'));

