1	@layer theme, base, components, utilities;
2	@import 'tailwindcss/theme.css' layer(theme);
3	@import 'tailwindcss/preflight.css' layer(base);
4	@import 'tailwindcss/utilities.css';
5	
6	@import '@spartan-ng/brain/hlm-tailwind-preset.css';
7	/* You can add global styles to this file, and also import other style files */
8	
9	/*
10	 * Hero Ops Console palette. Roles from the capstone build spec map onto
11	 * spartan's own tokens; the semantic and rail roles without a spartan
12	 * counterpart get their own tokens, exposed to Tailwind below.
13	 *
14	 * Deviations from the spec table, each forced by the WCAG arithmetic the
15	 * contrast gate runs (harness/gate/check-contrast.mjs):
16	 *   - light --primary-foreground is ink, not #ffffff: white on #d8891a is 2.80:1.
17	 *   - light --destructive is #c7353a, not #e5484d: white on #e5484d is 3.91:1.
18	 *   - light --info is #3d6ee0, not #4f7cf0: white on #4f7cf0 is 3.84:1.
19	 *   - light --ring is #a35f0c, not amber @ 35%: 35% amber over white is 1.4:1,
20	 *     and a translucent colour cannot be read by the gate or by a user.
21	 *   - dark --ring is solid amber, not amber @ 40%, for the same reason.
22	 */
23	:root {
24	  color-scheme: light;
25	
26	  --font-sans:
27	    -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, 'Noto Sans',
28	    sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji', 'Segoe UI Symbol', 'Noto Color Emoji';
29	
30	  --chart-1: oklch(0.646 0.222 41.116);
31	  --chart-2: oklch(0.6 0.118 184.704);
